      backup_text =
        "# NIGHT GROVE CROP PLOTTER #\n\
         # Plant a 3x3 grove: pick a seed, then plant cells, rows, or columns \
         #\n\n\
         type Plant = String in\n\
         type Grove = [[Plant]] in\n\
         type Row = Int in\n\
         type Col = Int in\n\n\
         type Model = (\n\
        \  grove = Grove,\n\
        \  currentSeed = Plant,\n\
        \  seedInventory = [Plant]\n\
         ) in\n\n\
         type Action =\n\
        \  + SelectSeed(Int)\n\
        \  + PlantSeed(Row, Col)\n\
        \  + Uproot(Row, Col)\n\
        \  + ClearGrove\n\
        \  + PlantRow(Row)\n\
        \  + PlantCol(Col)\n\
         in\n\n\
         let init: Model = (\n\
        \  grove = [\n\
        \    [\"\", \"\", \"\"],\n\
        \    [\"\", \"\", \"\"],\n\
        \    [\"\", \"\", \"\"]\n\
        \  ],\n\
        \  currentSeed = \"\240\159\140\177\",\n\
        \  seedInventory = [\"\240\159\140\177\", \"\240\159\140\191\", \
         \"\240\159\141\132\", \"\226\152\152\239\184\143\", \
         \"\240\159\140\184\"]\n\
         ) in\n\n\
         let setCell(grove: Grove, row: Row, col: Col, plant: Plant): Grove =\n\
        \  mapi(grove, fun (i, r) ->\n\
        \    if i == row\n\
        \    then mapi(r, fun (j, c) -> if j == col then plant else c)\n\
        \    else r)\n\
         in\n\n\
         let setRow(grove: Grove, targetRow: Row, plant: Plant): Grove =\n\
        \  mapi(grove, fun (i, row) ->\n\
        \    if i == targetRow\n\
        \    then map(row, fun _ -> plant)\n\
        \    else row)\n\
         in\n\n\
         let setCol(grove: Grove, col: Col, plant: Plant): Grove =\n\
        \  map(grove, fun row ->\n\
        \    mapi(row, fun (j, c) -> if j == col then plant else c))\n\
         in\n\n\
         let setAll(grove: Grove, plant: Plant): Grove =\n\
        \  map(grove, fun row -> map(row, fun _ -> plant))\n\
         in\n\n\
         let updateGrove(m: Model, f: Grove -> Grove): Model =\n\
        \  (\n\
        \    grove = f(m.grove),\n\
        \    currentSeed = m.currentSeed,\n\
        \    seedInventory = m.seedInventory\n\
        \  )\n\
         in\n\n\
         let update(action: Action, m: Model): (Model, Cmd) =\n\
        \  case action\n\
        \  | SelectSeed(idx) =>\n\
        \      (\n\
        \        (\n\
        \          grove = m.grove,\n\
        \          currentSeed = nth(m.seedInventory, idx),\n\
        \          seedInventory = m.seedInventory\n\
        \        ),\n\
        \        CmdNone\n\
        \      )\n\
        \  | PlantSeed(row, col) =>\n\
        \      (updateGrove(m, fun g -> setCell(g, row, col, m.currentSeed)), \
         CmdNone)\n\
        \  | Uproot(row, col) =>\n\
        \      (updateGrove(m, fun g -> setCell(g, row, col, \"\")), CmdNone)\n\
        \  | ClearGrove =>\n\
        \      (updateGrove(m, fun g -> setAll(g, \"\")), CmdNone)\n\
        \  | PlantRow(row) =>\n\
        \      (updateGrove(m, fun g -> setRow(g, row, m.currentSeed)), CmdNone)\n\
        \  | PlantCol(col) =>\n\
        \      (updateGrove(m, fun g -> setCol(g, col, m.currentSeed)), CmdNone)\n\
        \  end\n\
         in\n\n\
         # ===== VIEW ===== #\n\n\
         let view(model: Model): HTML =\n\
        \  let stripBtn(label: String, action: Action): HTML =\n\
        \    Button(\n\
        \      [\n\
        \        OnClick(action),\n\
        \        Style([\n\
        \          (\"width\", \"60px\"), (\"height\", \"22px\"), \
         (\"font-size\", \"12px\"),\n\
        \          (\"background\", \"#161b22\"), (\"color\", \"#8b949e\"),\n\
        \          (\"border\", \"1px solid #30363d\"), (\"cursor\", \
         \"pointer\")\n\
        \        ])\n\
        \      ],\n\
        \      [Text(label)]\n\
        \    )\n\
        \  in\n\
        \  Div(\n\
        \    [Style([\n\
        \      (\"max-width\", \"420px\"), (\"margin\", \"20px auto\"), \
         (\"padding\", \"20px\"),\n\
        \      (\"font-family\", \"monospace\"), (\"text-align\", \"center\"),\n\
        \      (\"background\", \"#0d1117\"), (\"color\", \"#c9d1d9\"),\n\
        \      (\"border\", \"1px solid #30363d\"), (\"border-radius\", \
         \"12px\")\n\
        \    ])],\n\
        \    [\n\
        \      H2([Style([(\"color\", \"#3fb950\"), (\"margin-bottom\", \
         \"2px\")])], [Text(\"\240\159\140\153 Crop Plotter\")]),\n\
        \      P(\n\
        \        [Style([(\"color\", \"#8b949e\"), (\"font-size\", \"12px\"), \
         (\"margin-top\", \"0\")])],\n\
        \        [Text(\"Click to plant, double-click to uproot\")]\n\
        \      ),\n\
        \      # Seed inventory #\n\
        \      Div(\n\
        \        [Style([(\"margin-bottom\", \"12px\"), (\"display\", \
         \"flex\"), (\"justify-content\", \"center\"), (\"gap\", \"5px\")])],\n\
        \        mapi(model.seedInventory, fun (idx, seed) ->\n\
        \          Button(\n\
        \            [\n\
        \              OnClick(SelectSeed(idx)),\n\
        \              Style([\n\
        \                (\"font-size\", \"22px\"), (\"padding\", \"6px \
         10px\"), (\"cursor\", \"pointer\"),\n\
        \                (\"background\", \"#161b22\"),\n\
        \                (\"border\", if seed == model.currentSeed then \"2px \
         solid #3fb950\" else \"1px solid #30363d\"),\n\
        \                (\"border-radius\", \"6px\")\n\
        \              ])\n\
        \            ],\n\
        \            [Text(seed)]\n\
        \          )\n\
        \        )\n\
        \      ),\n\
        \      # Column planting strip #\n\
        \      Div(\n\
        \        [Style([(\"display\", \"flex\"), (\"justify-content\", \
         \"center\"), (\"gap\", \"2px\"), (\"margin-left\", \"62px\")])],\n\
        \        mapi(nth(model.grove, 0), fun (col_idx, _cell) ->\n\
        \          stripBtn(\"\226\134\147 col\", PlantCol(col_idx))\n\
        \        )\n\
        \      ),\n\
        \      # Grove grid, each row prefixed by its row-planting button #\n\
        \      Div(\n\
        \        [Style([(\"display\", \"inline-block\"), (\"margin-top\", \
         \"2px\")])],\n\
        \        mapi(model.grove, fun (row_idx, row) ->\n\
        \          Div(\n\
        \            [Style([(\"display\", \"flex\"), (\"justify-content\", \
         \"center\"), (\"gap\", \"2px\"), (\"margin-bottom\", \"2px\")])],\n\
        \            [stripBtn(\"\226\134\146 row\", PlantRow(row_idx))] @\n\
        \            mapi(row, fun (col_idx, cell) ->\n\
        \              Button(\n\
        \                [\n\
        \                  OnClick(PlantSeed(row_idx, col_idx)),\n\
        \                  OnDoubleClick(Uproot(row_idx, col_idx)),\n\
        \                  Style([\n\
        \                    (\"width\", \"60px\"), (\"height\", \"60px\"), \
         (\"font-size\", \"26px\"),\n\
        \                    (\"background\", \"#161b22\"), (\"border\", \"1px \
         solid #30363d\"),\n\
        \                    (\"border-radius\", \"4px\"), (\"cursor\", \
         \"pointer\")\n\
        \                  ])\n\
        \                ],\n\
        \                [Text(if cell == \"\" then \" \" else cell)]\n\
        \              )\n\
        \            )\n\
        \          )\n\
        \        )\n\
        \      ),\n\
        \      # Controls #\n\
        \      Div(\n\
        \        [Style([(\"margin-top\", \"12px\")])],\n\
        \        [\n\
        \          Button(\n\
        \            [\n\
        \              OnClick(ClearGrove),\n\
        \              Style([(\"padding\", \"8px 16px\"), (\"background\", \
         \"#8b2252\"), (\"color\", \"white\"),\n\
        \                     (\"border\", \"none\"), (\"border-radius\", \
         \"6px\"), (\"cursor\", \"pointer\"),\n\
        \                     (\"font-family\", \"monospace\")])\n\
        \            ],\n\
        \            [Text(\"\240\159\140\190 Clear Grove\")]\n\
        \          )\n\
        \        ]\n\
        \      ),\n\
        \      Div(\n\
        \        [Style([(\"margin-top\", \"10px\"), (\"color\", \"#8b949e\"), \
         (\"font-size\", \"13px\")])],\n\
        \        [Text(\"Holding: \" ++ model.currentSeed)]\n\
        \      )\n\
        \    ]\n\
        \  )\n\
         in\n\n\
         let subs(_model: Model): Sub = SubNone in\n\n\
         # ===== TESTS ===== #\n\n\
         let step(acc: Model, a: Action): Model = let (m, _cmd) = update(a, \
         acc) in m in\n\
         let run(m: Model, actions: [Action]): Model = fold_left(actions, \
         step, m) in\n\n\
         hint \"planting a row fills that row\"\n\
         test\n\
        \  let (m, _cmd) = update(PlantRow(1), init) in\n\
        \  m.grove == [[\"\", \"\", \"\"], [\"\240\159\140\177\", \
         \"\240\159\140\177\", \"\240\159\140\177\"], [\"\", \"\", \"\"]]\n\
         end;\n\n\
         hint \"planting column 0 fills the left edge\"\n\
         test\n\
        \  let (m, _cmd) = update(PlantCol(0), init) in\n\
        \  m.grove == [[\"\240\159\140\177\", \"\", \"\"], \
         [\"\240\159\140\177\", \"\", \"\"], [\"\240\159\140\177\", \"\", \
         \"\"]]\n\
         end;\n\n\
         hint \"planting column 2 fills the right edge\"\n\
         test\n\
        \  let (m, _cmd) = update(PlantCol(2), init) in\n\
        \  m.grove == [[\"\", \"\", \"\240\159\140\177\"], [\"\", \"\", \
         \"\240\159\140\177\"], [\"\", \"\", \"\240\159\140\177\"]]\n\
         end;\n\n\
         hint \"row and column planting cross\"\n\
         test\n\
        \  let m = run(init, [PlantRow(0), PlantCol(1)]) in\n\
        \  m.grove == [[\"\240\159\140\177\", \"\240\159\140\177\", \
         \"\240\159\140\177\"], [\"\", \"\240\159\140\177\", \"\"], [\"\", \
         \"\240\159\140\177\", \"\"]]\n\
         end;\n\n\
         hint \"column planting uses the selected seed\"\n\
         test\n\
        \  let m = run(init, [SelectSeed(2), PlantCol(1)]) in\n\
        \  m.grove == [[\"\", \"\240\159\141\132\", \"\"], [\"\", \
         \"\240\159\141\132\", \"\"], [\"\", \"\240\159\141\132\", \"\"]]\n\
        \  && m.currentSeed == \"\240\159\141\132\"\n\
         end;\n\n\
         hint \"planting a single cell\"\n\
         test\n\
        \  let (m, _cmd) = update(PlantSeed(0, 0), init) in\n\
        \  m.grove == [[\"\240\159\140\177\", \"\", \"\"], [\"\", \"\", \"\"], \
         [\"\", \"\", \"\"]]\n\
         end;\n\n\
         hint \"uprooting clears one cell of a row\"\n\
         test\n\
        \  let m = run(init, [PlantRow(0), Uproot(0, 1)]) in\n\
        \  m.grove == [[\"\240\159\140\177\", \"\", \"\240\159\140\177\"], \
         [\"\", \"\", \"\"], [\"\", \"\", \"\"]]\n\
         end;\n\n\
         hint \"clearing the grove empties every cell\"\n\
         test\n\
        \  let m = run(init, [PlantCol(1), ClearGrove]) in\n\
        \  m.grove == [[\"\", \"\", \"\"], [\"\", \"\", \"\"], [\"\", \"\", \
         \"\"]]\n\
         end;\n\n\
         (init, update, view, subs)\n";
      refractors = "()";
    } )
